    }
}

public class StringReverser {
    // Reverses a string without using StringBuilder
    public static String reverse(String input) {
        char[] characters = input.toCharArray();
        int left = 0;
        int right = characters.length - 1;
        while (left < right) {
            char temp = characters[left];
            characters[left] = characters[right];
            characters[right] = temp;
            left++;
            right--;
        }
        return new String(characters);
    }

    public static void main(String[] args) {
        String original = "Hello, Java!";
        System.out.println("Original: " + original);
        System.out.println("Reversed: " + reverse(original));
    }
}

import java.util.HashMap;
import java.util.Map;

public class WordFrequencyCounter {
    public static void main(String[] args) {
        String text = "the quick brown fox jumps over the lazy dog the end";

        Map<String, Integer> frequencies = new HashMap<>();
        for (String word : text.split("\\s+")) {
            frequencies.put(word, frequencies.getOrDefault(word, 0) + 1);
        }

        for (Map.Entry<String, Integer> entry : frequencies.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }
    }
}

public class AnagramChecker {
    /**
     * Determines if two strings are anagrams of each other.
     */
    public static boolean areAnagrams(String first, String second) {
        String a = first.toLowerCase().replaceAll("\\s", "");
        String b = second.toLowerCase().replaceAll("\\s", "");

        if (a.length() != b.length()) {
            return false;
        }

        int[] counts = new int[26];
        for (int i = 0; i < a.length(); i++) {
            counts[a.charAt(i) - 'a']++;
            counts[b.charAt(i) - 'a']--;
        }

        for (int count : counts) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(areAnagrams("listen", "silent"));
        System.out.println(areAnagrams("hello", "world"));
    }
}

import java.util.Scanner;

public class FactorialCalculator {
    /**
     * Computes n! recursively.
     */
    public static long factorial(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();
        System.out.println(number + "! = " + factorial(number));
        scanner.close();
    }
}

public class FibonacciSeries {
    public static void main(String[] args) {
        int n = 10;
        long first = 0;
        long second = 1;

        System.out.print("Fibonacci series: " + first + " " + second);
        for (int i = 2; i < n; i++) {
            long next = first + second;
            System.out.print(" " + next);
            first = second;
            second = next;
        }
        System.out.println();
    }
}

import java.util.Scanner;

public class PrimeNumberChecker {
    /**
     * Checks whether a number is prime using trial division
     * up to the square root of the number.
     */
    public static boolean isPrime(int number) {
        if (number < 2) {
            return false;
        }
        for (int i = 2; i * i <= number; i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = scanner.nextInt();
        if (isPrime(num)) {
            System.out.println(num + " is a prime number");
        } else {
            System.out.println(num + " is not a prime number");
        }
        scanner.close();
    }
}

public class GcdCalculator {
    // Euclidean algorithm for greatest common divisor
    public static int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }

    public static void main(String[] args) {
        System.out.println("GCD(48, 18) = " + gcd(48, 18));
        System.out.println("GCD(100, 75) = " + gcd(100, 75));
    }
}

import java.util.Scanner;

public class ArmstrongNumber {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int number = scanner.nextInt();

        int original = number;
        int digits = String.valueOf(number).length();
        int sum = 0;

        while (number > 0) {
            int digit = number % 10;
            sum += Math.pow(digit, digits);
            number /= 10;
        }

        if (sum == original) {
            System.out.println(original + " is an Armstrong number");
        } else {
            System.out.println(original + " is not an Armstrong number");
        }
        scanner.close();
    }
}

