import java.util.HashSet;
import java.util.Set;

public class DuplicateFinder {
    /**
     * Prints all duplicate elements of the array using a HashSet.
     */
    public static void main(String[] args) {
        int[] values = {4, 2, 7, 4, 9, 2, 5, 7, 1};

        Set<Integer> seen = new HashSet<>();
        Set<Integer> duplicates = new HashSet<>();

        for (int value : values) {
            if (!seen.add(value)) {
                duplicates.add(value);
            }
        }

        System.out.println("Duplicates: " + duplicates);
    }
}

public class SecondLargestElement {
    public static void main(String[] args) {
        int[] arr = {12, 35, 1, 10, 34, 1};

        int largest = Integer.MIN_VALUE;
        int secondLargest = Integer.MIN_VALUE;

        for (int value : arr) {
            if (value > largest) {
                secondLargest = largest;
                largest = value;
            } else if (value > secondLargest && value != largest) {
                secondLargest = value;
            }
        }

        System.out.println("Largest: " + largest);
        System.out.println("Second largest: " + secondLargest);
    }
}

import java.util.Arrays;

public class ArrayRotation {
    /**
     * Rotates the array to the right by k positions
     * using the reversal algorithm.
     */
    public static void rotate(int[] arr, int k) {
        int n = arr.length;
        k = k % n;
        reverse(arr, 0, n - 1);
        reverse(arr, 0, k - 1);
        reverse(arr, k, n - 1);
    }

    private static void reverse(int[] arr, int start, int end) {
        while (start < end) {
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5, 6, 7};
        rotate(numbers, 3);
        System.out.println(Arrays.toString(numbers));
    }
}

/**
 * Demonstrates encapsulation with a simple bank account class.
 */
public class BankAccount {
    private String owner;
    private double balance;

    public BankAccount(String owner, double initialBalance) {
        this.owner = owner;
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
            System.out.println("Deposited: " + amount);
        }
    }

    public void withdraw(double amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
            System.out.println("Withdrawn: " + amount);
        } else {
            System.out.println("Insufficient funds");
        }
    }

    public double getBalance() {
        return balance;
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount("Alice", 100.0);
        account.deposit(50.0);
        account.withdraw(30.0);
        account.withdraw(500.0);
        System.out.println("Final balance: " + account.getBalance());
    }
}

/**
 * Demonstrates inheritance and method overriding.
 */
class Animal {
    protected String name;

    public Animal(String name) {
        this.name = name;
    }

    public void makeSound() {
        System.out.println(name + " makes a sound");
    }
}

class Dog extends Animal {
    public Dog(String name) {
        super(name);
    }

    @Override
    public void makeSound() {
        System.out.println(name + " barks: Woof!");
    }
}

class Cat extends Animal {
    public Cat(String name) {
        super(name);
    }

    @Override
    public void makeSound() {
        System.out.println(name + " meows: Meow!");
    }
}

public class InheritanceDemo {
    public static void main(String[] args) {
        Animal[] animals = {
            new Dog("Rex"),
            new Cat("Whiskers"),
            new Animal("Generic")
        };

        for (Animal animal : animals) {
            animal.makeSound();
        }
    }
}

interface Shape {
    double area();
    double perimeter();
}

class Circle implements Shape {
    private final double radius;

    public Circle(double radius) {
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public double perimeter() {
        return 2 * Math.PI * radius;
    }
}

class Rectangle implements Shape {
    private final double width;
    private final double height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public double perimeter() {
        return 2 * (width + height);
    }
}

public class ShapeDemo {
    public static void main(String[] args) {
        Shape[] shapes = {new Circle(5), new Rectangle(4, 6)};
        for (Shape shape : shapes) {
            System.out.printf("Area: %.2f, Perimeter: %.2f%n",
                    shape.area(), shape.perimeter());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

/**
 * A simple student management example demonstrating
 * classes, lists and basic CRUD operations.
 */
class Student {
    private final int id;
    private String name;
    private double grade;

    public Student(int id, String name, double grade) {
        this.id = id;
        this.name = name;
        this.grade = grade;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public double getGrade() { return grade; }

    @Override
    public String toString() {
        return String.format("Student{id=%d, name='%s', grade=%.1f}", id, name, grade);
    }
}

public class StudentManager {
    private final List<Student> students = new ArrayList<>();

    public void addStudent(Student student) {
        students.add(student);
    }

    public Student findById(int id) {
        for (Student student : students) {
            if (student.getId() == id) {
                return student;
            }
        }
        return null;
    }

    public double averageGrade() {
        if (students.isEmpty()) {
            return 0;
        }
        double sum = 0;
        for (Student student : students) {
            sum += student.getGrade();
        }
        return sum / students.size();
    }

    public static void main(String[] args) {
        StudentManager manager = new StudentManager();
        manager.addStudent(new Student(1, "Alice", 4.5));
        manager.addStudent(new Student(2, "Bob", 3.8));
        manager.addStudent(new Student(3, "Charlie", 4.9));

        System.out.println("Found: " + manager.findById(2));
        System.out.printf("Average grade: %.2f%n", manager.averageGrade());
    }
}

/**
 * Demonstrates an abstract class with template method pattern.
 */
abstract class Vehicle {
    protected String model;

    public Vehicle(String model) {
        this.model = model;
    }

    // Template method
    public void startJourney() {
        checkFuel();
        start();
        System.out.println(model + " is on its way!");
    }

    protected void checkFuel() {
        System.out.println("Checking fuel level...");
    }

    protected abstract void start();
}

class Car extends Vehicle {
    public Car(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Turning ignition key...");
    }
}

class ElectricScooter extends Vehicle {
    public ElectricScooter(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Pressing power button...");
    }
}

public class VehicleDemo {
    public static void main(String[] args) {
        Vehicle[] vehicles = {new Car("Toyota"), new ElectricScooter("Xiaomi")};
        for (Vehicle vehicle : vehicles) {
            vehicle.startJourney();
        }
    }
}

import java.util.Scanner;

public class SafeDivision {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        try {
            System.out.print("Enter numerator: ");
            int a = scanner.nextInt();
            System.out.print("Enter denominator: ");
            int b = scanner.nextInt();

            int result = a / b;
            System.out.println("Result: " + result);
        } catch (ArithmeticException e) {
            System.out.println("Error: division by zero is not allowed");
        } catch (Exception e) {
            System.out.println("Invalid input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

/**
 * Custom exception example: validating user age.
 */
class InvalidAgeException extends Exception {
    public InvalidAgeException(String message) {
        super(message);
    }
}

public class AgeValidator {
    public static void validateAge(int age) throws InvalidAgeException {
        if (age < 0) {
            throw new InvalidAgeException("Age cannot be negative: " + age);
        }
        if (age > 150) {
            throw new InvalidAgeException("Age is unrealistically large: " + age);
        }
        System.out.println("Age " + age + " is valid");
    }

    public static void main(String[] args) {
        int[] testAges = {25, -5, 200};
        for (int age : testAges) {
            try {
                validateAge(age);
            } catch (InvalidAgeException e) {
                System.out.println("Validation failed: " + e.getMessage());
            }
        }
    }
}

import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class FileReadWriteDemo {
    public static void main(String[] args) {
        String fileName = "notes.txt";

        // Write lines to the file
        try (BufferedWriter writer = new BufferedWriter(new FileWriter(fileName))) {
            writer.write("First line");
            writer.newLine();
            writer.write("Second line");
            writer.newLine();
        } catch (IOException e) {
            System.out.println("Write error: " + e.getMessage());
            return;
        }

        // Read the file back
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println("Read: " + line);
            }
        } catch (IOException e) {
            System.out.println("Read error: " + e.getMessage());
        }
    }
}

import java.util.Scanner;

public class GradeCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter your score (0-100): ");
        int score = scanner.nextInt();

        char grade;
        if (score >= 90) {
            grade = 'A';
        } else if (score >= 80) {
            grade = 'B';
        } else if (score >= 70) {
            grade = 'C';
        } else if (score >= 60) {
